/** Appends binary commands; see schema/protocol.toml for the layout. */
export class CmdWriter {
  private buf: ArrayBuffer;
  private dv: DataView;
  private u8: Uint8Array;
  private pos = 0;
  /** Offsets where each command starts, so batches can be split between commands. */
  private starts: number[] = [];

  constructor(capacity = 1 << 16) {
    this.buf = new ArrayBuffer(capacity);
    this.dv = new DataView(this.buf);
    this.u8 = new Uint8Array(this.buf);
  }

  get length(): number {
    return this.pos;
  }

  private head(op: number, bytes: number, frame: number): number {
    const need = this.pos + HEADER_BYTES + bytes;
    if (need > this.buf.byteLength) this.grow(need);
    const p = this.pos;
    this.starts.push(p);
    this.u8.fill(0, p, need);
    this.dv.setUint16(p, op, true);
    this.dv.setUint32(p + 4, bytes, true);
    this.dv.setFloat64(p + 8, frame, true);
    this.pos = need;
    return p + HEADER_BYTES;
  }

  private grow(need: number): void {
    let cap = this.buf.byteLength * 2;
    while (cap < need) cap *= 2;
    const next = new ArrayBuffer(cap);
    new Uint8Array(next).set(this.u8.subarray(0, this.pos));
    this.buf = next;
    this.dv = new DataView(next);
    this.u8 = new Uint8Array(next);
  }

  /** The bytes written so far, without copying. */
  bytes(): Uint8Array {
    return this.u8.subarray(0, this.pos);
  }

  /** Forget everything written. (The Reset command is reset(frame).) */
  clear(): void {
    this.pos = 0;
    this.starts.length = 0;
  }

  /** Copies the batch out as ArrayBuffers of at most maxBytes each, split between commands, then resets. */
  take(maxBytes: number = CONST.cmdCapacity): ArrayBuffer[] {
    const out: ArrayBuffer[] = [];
    let from = 0;
    for (let i = 0; i < this.starts.length; i++) {
      const end = i + 1 < this.starts.length ? this.starts[i + 1] : this.pos;
      if (end - from > maxBytes && this.starts[i] > from) {
        out.push(this.buf.slice(from, this.starts[i]));
        from = this.starts[i];
      }
    }
    if (this.pos > from) out.push(this.buf.slice(from, this.pos));
    this.clear();
    return out;
  }

  /** Set a parameter to a normalized value in 0..1. */
  setParam(frame: number, id: number, value: number): void {
    const o = this.head(1, 8, frame);
    this.dv.setUint16(o + 0, id, true);
    this.dv.setFloat32(o + 4, value, true);
  }

  /** Start a note. noteId is chosen by the host and matched by NoteOff. */
  noteOn(frame: number, note: number, channel: number, velocity: number, noteId: number): void {
    const o = this.head(2, 16, frame);
    this.dv.setUint8(o + 0, note);
    this.dv.setUint8(o + 1, channel);
    this.dv.setFloat32(o + 4, velocity, true);
    this.dv.setUint32(o + 8, noteId, true);
  }

  /** Release a note: by noteId when it's non-zero, else by note and channel. */
  noteOff(frame: number, note: number, channel: number, velocity: number, noteId: number): void {
    const o = this.head(3, 16, frame);
    this.dv.setUint8(o + 0, note);
    this.dv.setUint8(o + 1, channel);
    this.dv.setFloat32(o + 4, velocity, true);
    this.dv.setUint32(o + 8, noteId, true);
  }

  /** Release every voice (MIDI CC 123). */
  allNotesOff(frame: number): void {
    this.head(4, 0, frame);
  }

  /** Fade every voice out within a few milliseconds (MIDI CC 120). */
  allSoundOff(frame: number): void {
    this.head(5, 0, frame);
  }

  /** Pitch wheel position, -1..1. */
  pitchBend(frame: number, channel: number, value: number): void {
    const o = this.head(6, 8, frame);
    this.dv.setUint8(o + 0, channel);
    this.dv.setFloat32(o + 4, value, true);
  }

  /** A MIDI continuous controller, value 0..1. */
  controller(frame: number, channel: number, cc: number, value: number): void {
    const o = this.head(7, 8, frame);
    this.dv.setUint8(o + 0, channel);
    this.dv.setUint8(o + 1, cc);
    this.dv.setFloat32(o + 4, value, true);
  }

  /** Channel aftertouch, 0..1. */
  channelPressure(frame: number, channel: number, value: number): void {
    const o = this.head(8, 8, frame);
    this.dv.setUint8(o + 0, channel);
    this.dv.setFloat32(o + 4, value, true);
  }

  /** Per-note aftertouch, 0..1. */
  polyPressure(frame: number, note: number, channel: number, value: number, noteId: number): void {
    const o = this.head(9, 16, frame);
    this.dv.setUint8(o + 0, note);
    this.dv.setUint8(o + 1, channel);
    this.dv.setFloat32(o + 4, value, true);
    this.dv.setUint32(o + 8, noteId, true);
  }

  /** Choose which taps the engine records (bit i = tap i). */
  setTaps(frame: number, mask: number): void {
    const o = this.head(16, 8, frame);
    this.dv.setUint32(o + 0, mask, true);
  }

  /** Clear all DSP state (voices, smoothers, tails) but keep parameters. */
  reset(frame: number): void {
    this.head(17, 0, frame);
  }

  /** Test hooks; see [debug]. */
  debug(frame: number, code: number, arg: number): void {
    const o = this.head(31, 8, frame);
    this.dv.setUint32(o + 0, code, true);
    this.dv.setFloat32(o + 4, arg, true);
  }
}

